#include <stdio.h>
#include <stdlib.h>

long long count_at_most(const int *x, int n, int limit) {
    if (limit < 0) return 0;

    int left = 0;
    long long sum = 0;
    long long count = 0;

    for (int right = 0; right < n; right++) {
        sum += x[right];

        while (sum > limit) {
            sum -= x[left++];
        }

        count += right - left + 1;
    }

    return count;
}

int main(void) {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) return 0;

    int *x = malloc((size_t)n * sizeof(int));
    if (x == NULL) return 0;

    for (int i = 0; i < n; i++) {
        scanf("%d", &x[i]);
    }

    long long result = count_at_most(x, n, k) - count_at_most(x, n, k - 1);
    printf("%lld\n", result);

    free(x);
    return 0;
}
